var d = System.AppDomain.CurrentDomain;
var sc = UnityEngine.SceneManagement.SceneManager.GetActiveScene().name;
var camp = LevelSelectionController.currentCampaign;
string key = sc + "|" + (camp == null ? "" : camp.name) + "|" + LevelSelectionController.CurrentLevelNum;
var ic = System.Globalization.CultureInfo.InvariantCulture;
float now = UnityEngine.Time.realtimeSinceStartup;
var last = d.GetData("uimtest.settle") as string;
int cut = last == null ? -1 : last.LastIndexOf('|');
if (last == null || last.Substring(0, cut) != key) {
  d.SetData("uimtest.settle", key + "|" + now.ToString(ic));
  return "waiting: " + sc + " just came up";
}
float since = now - float.Parse(last.Substring(cut + 1), ic);
if (sc == "LoadingScreen") return "waiting: loading";
if (LevelSelectionController.IsCampaignScene) {
  if (HeroController.Instance == null || Map.Instance == null || GameModeController.Instance == null) return "waiting: the level is still being built";
  var wt = typeof(GameModeController).GetField("winTimer", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
  if (GameModeController.IsLevelFinished() && (float)wt.GetValue(GameModeController.Instance) < 999999f) return "waiting: the level finished and is moving on";
}
if (since < 4f) return "waiting: " + sc + " unchanged for " + since.ToString("0.0", ic) + " s";
return "settled in " + sc;

var d = System.AppDomain.CurrentDomain;
var fl = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static;
string lv = "0|1";
if (LevelSelectionController.IsCampaignScene && LevelSelectionController.currentCampaign != null) {
  var all = typeof(Unity_Inspector_Mod.StateModifier).GetField("CampaignNames", fl).GetValue(null) as string[];
  for (int i = 0; i < all.Length; i++) if (string.Equals(all[i], LevelSelectionController.currentCampaign.name, System.StringComparison.OrdinalIgnoreCase)) lv = i + "|" + LevelSelectionController.CurrentLevelNum;
}
d.SetData("uimtest.level", lv);
d.SetData("uimtest.settle", null);
return "recorded level=" + lv;

var reply = Newtonsoft.Json.Linq.JObject.Parse(new Unity_Inspector_Mod.MessageHandler().HandleMessage("{\"id\":\"param-check\",\"method\":\"simulate_input\",\"params\":{\"action\":\"jump\",\"count\":2.5}}", null));
Newtonsoft.Json.Linq.JToken error = reply["error"];
if (error == null && reply["result"] is Newtonsoft.Json.Linq.JObject) error = reply["result"]["error"];
return reply["success"] + "|" + error;

var ids = new System.Collections.Generic.List<string>();
for (int i = 0; i < 40; i++) {
  var r = (Newtonsoft.Json.Linq.JObject)Unity_Inspector_Mod.InputSimulator.StartPlan(Newtonsoft.Json.Linq.JObject.Parse("{\"sequence\":[{\"wait\":1}]}"), null);
  ids.Add(r["planId"].ToString());
}
System.AppDomain.CurrentDomain.SetData("uimtest.plans", ids[0] + "|" + ids[39]);
return "started " + ids.Count + " unpolled plans";

var d = System.AppDomain.CurrentDomain;
var p = ((string)d.GetData("uimtest.plans")).Split('|');
d.SetData("uimtest.plans", null);
System.Func<string, string> read = id => Unity_Inspector_Mod.InputSimulator.PlanStatus(Newtonsoft.Json.Linq.JObject.Parse("{\"planId\":" + id + "}")).ToString();
string first = read(p[0]), last = read(p[1]);
return "first=" + (first.Contains("No input plan") ? "evicted" : "kept") + " last=" + (last.Contains("\"success\": true") ? "kept" : "missing: " + last);

var handler = new Unity_Inspector_Mod.MessageHandler();
var owner = new object();
var started = Newtonsoft.Json.Linq.JObject.Parse(handler.HandleMessage("{\"id\":\"cancel\",\"method\":\"simulate_input\",\"params\":{\"action\":\"right\",\"duration\":5000}}", owner));
var id = (int)started["result"]["planId"];
System.AppDomain.CurrentDomain.SetData("uimtest.cancel", new object[] { owner, id });
return "active=" + Unity_Inspector_Mod.InputSimulator.Active;

var handler = new Unity_Inspector_Mod.MessageHandler();
var d = System.AppDomain.CurrentDomain;
var held = (object[])d.GetData("uimtest.cancel");
d.SetData("uimtest.cancel", null);
var running = Unity_Inspector_Mod.InputSimulator.Active;
string id = held[1].ToString();
string cancel = "{\"id\":\"cancel\",\"method\":\"cancel_input_plan\",\"params\":{\"planId\":" + id + "}}";
string other = Newtonsoft.Json.Linq.JObject.Parse(handler.HandleMessage(cancel, new object()))["result"]["cancelled"].ToString();
string mine = Newtonsoft.Json.Linq.JObject.Parse(handler.HandleMessage(cancel, held[0]))["result"]["cancelled"].ToString();
string again = Newtonsoft.Json.Linq.JObject.Parse(handler.HandleMessage(cancel, held[0]))["result"]["cancelled"].ToString();
string poll = handler.HandleMessage("{\"id\":\"cancel\",\"method\":\"input_plan\",\"params\":{\"planId\":" + id + "}}", held[0]);
return "running=" + running + " other=" + other + " mine=" + mine + " again=" + again + " poll=" + (poll.Contains("No input plan") ? "gone" : poll);

var handler = new Unity_Inspector_Mod.MessageHandler();
var missing = Newtonsoft.Json.Linq.JObject.Parse(handler.HandleMessage("{\"id\":\"cancel\",\"method\":\"cancel_input_plan\",\"params\":{}}", null));
var none = Newtonsoft.Json.Linq.JObject.Parse(handler.HandleMessage("{\"id\":\"cancel\",\"method\":\"cancel_input_plan\",\"params\":{\"planId\":2147483647}}", null));
return "missing=" + missing["error"] + " none=" + none["result"]["cancelled"];

var d = System.AppDomain.CurrentDomain;
var rec = (d.GetData("uimtest.level") as string) ?? "0|1";
d.SetData("uimtest.level", null);
var p = rec.Split('|');
var r = Unity_Inspector_Mod.StateModifier.GoToLevel(int.Parse(p[0]), int.Parse(p[1]));
var j = Newtonsoft.Json.Linq.JToken.FromObject(r);
return "loading recorded level " + rec + ": success=" + j["success"] + " " + j.ToString(Newtonsoft.Json.Formatting.None);

var d = System.AppDomain.CurrentDomain;
string log = "";
var levelRec = d.GetData("uimtest.level") as string;
d.SetData("uimtest.level", null);
d.SetData("uimtest.settle", null);
if (levelRec != null) {
  var lp = levelRec.Split('|');
  var lr = Unity_Inspector_Mod.StateModifier.GoToLevel(int.Parse(lp[0]), int.Parse(lp[1]));
  var lj = Newtonsoft.Json.Linq.JToken.FromObject(lr);
  log += "loading recorded level " + levelRec + ": success=" + lj["success"] + " " + lj.ToString(Newtonsoft.Json.Formatting.None);
}
return log.Length == 0 ? "nothing to restore" : log;
